import json

from dojo_support import fail, say
from words import top_k, word_count


def show(o):
    return json.dumps(o, ensure_ascii=False)


def why(got, default):
    """What is actually wrong with a result, so the hint matches the mistake rather than the test's name."""
    ks = list(got)
    if "" in ks:
        return "empty"
    if any(k != k.lower() for k in ks):
        return "case"
    if any(not k.isalnum() for k in ks):
        return "punctuation"
    return default


def test_lv1_basic():
    got, want = dict(sorted(word_count("the cat saw the hat").items())), {"cat": 1, "hat": 1, "saw": 1, "the": 2}
    if got != want:
        fail(why(got, "wrong_count"), say(f'"the cat saw the hat" 的结果应该是 {show(want)}，实际是 {show(got)}。', f'For "the cat saw the hat" the result should be {show(want)}, got {show(got)}.'))


def test_lv1_case():
    got, want = dict(sorted(word_count("The the THE cat").items())), {"cat": 1, "the": 3}
    if got != want:
        fail(why(got, "case"), say(f'"The the THE cat" 里大小写不同的同一个词被分开数了：期望 {show(want)}，实际 {show(got)}。', f'In "The the THE cat" the same word in different case was counted separately: expected {show(want)}, got {show(got)}.'))


def test_lv1_punctuation():
    got, want = dict(sorted(word_count("Hello, world! Hello.").items())), {"hello": 2, "world": 1}
    if got != want:
        fail(why(got, "punctuation"), say(f'"Hello, world! Hello." 的结果里有带标点的词：期望 {show(want)}，实际 {show(got)}。', f'For "Hello, world! Hello." some words still carry punctuation: expected {show(want)}, got {show(got)}.'))


def test_lv1_empty():
    got, want = dict(sorted(word_count("   ").items())), {}
    if got != want:
        fail(why(got, "empty"), say(f'文本 "   " 里没有词，期望结果为空，实际是 {show(got)}。', f'The text "   " has no words, so the result should be empty; got {show(got)}.'))

